const slots = $slots;
const minutesOf = (hour) => hour * 60;
const limit = minutesOf(slots.openUntil) - minutesOf(slots.breakUntil);
const ticketKey = (day, hour) => day.toLowerCase() + hour.toFixed(2);
const first = minutesOf(slots.first.hour);
const second = minutesOf(slots.second.hour);
const open = first <= minutesOf(slots.openUntil) && second <= minutesOf(slots.openUntil);
const firstOk = first <= minutesOf(slots.breakFrom);
const secondOk = second <= minutesOf(slots.breakUntil);
if (open && !firstOk && !secondOk) { throw new Error("the two attempts both miss the open window"); }
if (open && firstOk && secondOk) { throw new Error("the two attempts both reach the open window"); }
const ticket = firstOk ? ticketKey(slots.first.day, slots.first.hour) : ticketKey(slots.second.day, slots.second.hour);
return "Success on " + ticket + ". The first attempt is rejected because it arrives " + minutesOf(slots.first.hour) + " minutes into the " + slots.openUntil + "–" + slots.breakUntil + " window, while the second is accepted because it arrives " + minutesOf(slots.second.hour) + " minutes into the " + slots.breakFrom + "–" + slots.breakUntil + " window.";

